          "descJa": "王賁と李信は軍を東北へ向け遼東へ遠征し、襄平を攻め破って燕王喜を捕虜とし、燕国は完全に滅亡した。間もなく軍を返して北の代郡を攻め、代王嘉を捕虜とし、趙氏の残党も途絶えた。同年、南線では王翦の大軍が長江を渡り、楚の旧領である江南を平定し、越の君主を降伏させて会稽郡を設置した。これにより、天下の六国で残るは東海のほとりに孤立する斉国のみとなった。"
