          "titleEn": "Diplomatic Mission to Chaisang — Forging the Wu Alliance",
          "descZh": "曹操が荊州へ南下し、劉備が当陽長坂で敗走すると、諸葛亮は危急に際して長江を下り柴桑へ赴き孫権を説得した。曹軍の遠征による疲弊と北方人が水戦に不慣れな点を分析し、孫劉同盟を成立させて曹軍に対抗させた。",
