          "descZh": "州吏の李昌は玄奘の誠実に感じ入り、密かに追捕の牒文を破り捨てた。玄奘は夜に葫蘆河を渡り、一人で五つの烽火台を突破したが、八百里の莫賀延磧で誤って水をこぼし、四夜五日、一滴の水も口にできなかった。絶体絶命の窮地から生還し、ついに伊吾に到着した。",
