          "descJa": "戒日王は曲女城で無遮大会を設けた。五天竺の十八国王と数千人の僧俗が参加した。玄奘は論主となり、自身の著した論を会場の門外に掲げた。十八日間、一人として反論できる者はいなかったため、大乗からは「大乗天」、小乗からは「解脱天」と尊称された。"
