          "descZh": "山東兗州任城に家を置き、杜甫と共に齊魯を遊歴し、范十の隠居を訪ね、泰山、徂徠に登り、紫極宮で道籙を受けた。東魯を離れ越中へ南遊する際、『夢遊天姥吟留別』を賦し、「安能摧眉折腰事権貴、使我不得開心顔」（いずくんぞ眉を摧き腰を折りて権貴に事え、我をして開心顔を得しめざらんや）という千古の絶唱を放った。",
