          "descZh": "徐州知事であった時、黄河が澶州曹村で決壊し、洪水が徐州城下に迫った。蘇軾は粗末な服と草履で城壁に泊まり込み、親しく禁軍と民夫を率いて長堤を築き、七十余日死守して全城を守り抜いた。水が引いた後、東門に黄楼を築いて水害を鎮めた。",
