          "descZh": "元祐の更化期には翰林學士、杭州・潁州・揚州・定州の知州として召還されたが、紹聖元年（1094年）に哲宗が親政を開始し新党が復権すると、六十歳に近かった蘇軾は遠く嶺南の恵州へ貶謫・安置された。彼は犀帯を寄付して東新橋と西新橋の修築を助けた。",
