          "descZh": "十八歳で南昌から妻を迎え余姚へ帰る途中、舟が江西広信（現在の上饒）に停泊した際、崇仁学派の大儒である婁諒（婁一齋）を特別に訪ねて謁見した。婁諒は彼に宋儒の格物窮理の要旨を説き明かし、「聖人は必ず学んで到達できる」と語った。守仁は深くこれに共感し、これより聖学に篤志し、帰郷後、考亭朱子の遺書を遍く読んだ。",
