          "descZh": "魏王豹が漢を裏切ると、韓信は黄河渡河作戦を敢行。臨晉に大軍と船を誇示して敵主力を引きつける一方、密かに上流の夏陽（韓城）から木樽（木罌缻）を縛り合わせた筏で黄河を急襲渡河し、背後から魏の都・安邑を直撃して魏王豹を生け捕りにした。",
