          "titleJa": "安史の乱での防衛と長安での刑死",
          "descJa": "安史の乱が勃発すると副元帥として陝州・潼関を守備し、封常清とともに長安への要害・潼関を死守して安禄山軍の進撃を阻止した。しかし監軍の宦官辺令誠の讒言によって、玄宗の勅命により陣中で不当に斬刑に処された。死に臨んで部下を見回し「我が退却したるは罪なれど、盗用・謀反は冤罪なり！」と叫ぶと、兵士全員が「冤罪なり！」と天に向かって号泣した。"
