          "descZh": "大北伐に先立ち後顧の憂いを断つため、劉裕は名将・朱齢石を抜擢して益州の譙縦（後蜀）討伐を命じ、密書にて「敵の意表を突き、主力を外水（岷江）から成都へ直進させよ」との奇策を授けた。晋軍は険難を突破して成都を陥落させ、譙縦は自縊。巴蜀全域が再び東晋の版図に復帰した。",
