          "descZh": "先鋒の王鎮悪は蒙衝小艦で激流の渭水を遡上し、長安の渭橋に上陸するや舟を全て河に流して「ここは長安の北門、死して生を求むべし！」と兵を鼓舞、後秦軍数万を撃破して長安を陥落させ、皇帝・姚泓を降伏させた。入城した劉裕は秦漢の旧都・長安を百年ぶりに漢人王朝の支配下に取り戻した（420年に禅譲を受け南朝・宋の武帝として即位）。後世、辛棄疾に「金戈鉄馬、気呑万里如虎」と讃えられた。",
