          "titleEn": "Bulwark of Longyou: Routing Jiang Wei at Didao & Duangu",
          "descZh": "屯田の才と軍事眼を司馬懿に見出された鄧艾は、隴西の最前線で蜀の大将軍・姜維の北伐と対峙。255年に狄道の包囲を解き、翌256年には段谷の戦いで姜維の進軍ルートを完全に読み切って待ち伏せし、蜀軍を大破して姜維の北伐の鋭気を挫いた。",
