          "descJa": "陰平から先は道すら絶えた断崖絶壁（摩天嶺）であった。山を穿ち木橋を架けて進んだが、最後は崖に行き当たり食糧も尽き果てた。その時、六十七歳の鄧艾は自ら毛布（氈）に身を包んで断崖から谷底へ転がり落ち、将兵も木にすがって次々と降下。突如天から降ったかのように現れた魏軍に、江油城の守将・馬邈は戦わずして降伏した。"
