          "descZh": "ホラズム・シャー朝のオトラル総督がモンゴルの通商使節団四百五十人を虐殺したことに激怒したチンギス・カンは、四人の息子（ジョチ・チャガタイ・オゴデイ・トゥルイ）を総動員し十数万の大軍で西方大遠征を敢行。アルタイ山脈とイリ渓谷を越えてオトラルへ到達すると、チャガタイとオゴデイにオトラル包囲を命じ、ジョチをシルダリア下流へ、自らはトゥルイとともにキジルクム砂漠の横断へと向かった。",
