          "descZh": "臨安陥落後も文天祥・張世傑・陸秀夫らが幼帝・祥興帝を擁して広東の崖山に千余隻の船団を連結して最後の抵抗を続けた。クビライが派遣した張弘範・李恒の水軍が崖山を完全包囲して撃破。陸秀夫は幼帝を背負って海に身を投げ、南宋は完全に滅亡。唐末以来約三百七十年間にわたった中国分裂時代はここに終焉し、全土統一が成し遂げられた。",
