          "descZh": "西本願寺の大谷光瑞は、ロンドン留学中に中央アジア仏教史の解明を志し、渡辺哲信・堀賢雄・本多恵隆・井上弘円とともに第1次探検隊を結成。1902年8月にサンクトペテルブルクを発ち、中央アジアのオシから標高4000メートル超のパミール高原（葱嶺）の難所キジル・アルト峠を越えてカシュガルに入り、タシュクルガン（玄奘『大唐西域記』の朅盤陀国）で部隊を分けて調査を開始した。",
