          "descZh": "1979年、改革開放の幕開けとともにNHKと中国中央電視台（CCTV）による史上初の日中共同大型取材が実現。シルクロードの起点・長安（西安）の大雁塔や鐘楼、始皇帝陵・兵馬俑、法門寺などを取材して西域への旅を開始した。井上靖・司馬遼太郎・陳舜臣らの紀行、石坂浩二の名ナレーション、喜多郎のシンセサイザー音楽が日本中に空前のシルクロード・ブームを巻き起こした。",
