          "descJa": "天山山脈南麓の灼熱の窪地トゥルファンで、地下水路「カレーズ（坎児井）」が緑を育む仕組みと、火焔山、高昌故城、交河故城、ベゼクリク千仏洞を取材。さらに1979年に開通したばかりの天山山脈を貫く南疆鉄道（吐魯番〜コルラ間476キロ）の開通後間もない列車に外国人として初めて同乗し、天山北路と南路を結ぶ新たな大動脈を記録した。",
