          "descJa": "名僧・鳩摩羅什を生み、かつて中国・日本（雅楽）にも影響を与えた亀茲楽とキジル千仏洞の都クチャ（亀茲）にて、ウイグル伝統音楽十二ムカムや琵琶・箜篌の源流を追究。続いて天山山脈を越えて天山北路のバインブルクおよびイリ草原へ入り、漢の武帝が渇望した「天馬（汗血馬）」の血を引くイリ馬とカザフ遊牧民の移動生活を取材した。",
