      "descJa": "北は渭水に臨み、南は秦嶺に依る。「八水繞長安」と称される關中の要衝に位置した。周、秦、西漢、新、前趙、前秦、後秦、西魏、北周、隋、唐など十余りの王朝がここに都を置き、絲綢之路の東方起点、また漢唐代の国際都会として栄えた。",
