      "descZh": "北は汝洛に通じ、南は江陵を扼し、西は武当を抑え、東は江漢を望む。三面を水に囲まれ、一面を山に臨む。三国時代には関羽が水攻めで七軍を壊滅させ、東晋・南朝の北伐では、南宋の孟珙と呂文徳が堅守してモンゴル軍に抗戦するなど、歴代にわたり南北攻防の要衝「天下の腰膂」であった。",
