      "descZh": "古くは肅州と呼ばれ、その管轄は瓜州（晋昌）を含んだ。南は祁連山の氷河に接し、北は馬鬃山を扼する。前121年、漢の武帝の元狩二年、霍去病が匈奴を大破した後、酒泉郡が初めて置かれた（伝承によれば、霍去病が皇帝から賜った酒を泉に注ぎ、全軍と共に飲んだことに由来する）。唐代には、瓜州は玄奘が西域へ旅立った地であり、安西都護府への要衝であった。",
