      "descZh": "古称沈州、沈阳中卫、盛京、奉天，居辽河平原浑河北岸，东依长白余脉、南通辽东半岛。天命十年（1625年）努尔哈赤自辽阳迁都沈阳，皇太极于此改国号大清、尊为盛京并营建沈阳故宫，入关后定为清代留都。",
