      "descZh": "牡丹江（古くは忽汗水）中流域の盆地に位置する。唐代、靺靨の大祚榮が渤海國を建国し、唐の長安城を模して上京龍泉府（現在の寧安市東京城）を建設、「海東盛國」と称した。清初には寧古塔の昂邦章京（後に寧古塔将軍と改称）が置かれ、松花江、烏蘇里江、黒龍江流域および庫頁島を管轄した。",
