      "descZh": "管轄する阿城（阿什河流域、古くは按出虎水）は、女真の完顔部が勃興した地である。1115年、完顔阿骨打がここで帝位に就き大金國を建国、上京會寧府を都とした。相次いで遼を滅ぼし、北宋を破り、金太祖、太宗、熙宗、および海陵王の初年までの四朝38年間、12世紀の東北亞における政治中枢であった。",
