      "descZh": "古くは輪臺（唐代の北庭輪臺県）、迪化と呼ばれ、天山ボグダ峰北麓とジュンガル盆地南縁の通路に位置する。唐代にはウラ泊に輪臺城が築かれ、シルクロードの商税が徴収された（岑参の詩「輪臺東門送君去」はこの地を指す）。清の乾隆28年（1763年）に迪化城が築かれ、光緒10年（1884年）に新疆省が設置されると省都と定められた。",
