      "descJa": "古くは晋興、邕州、南寧路と呼ばれ、左江と右江が合流した後の邕江河谷盆地に位置し、南は十万大山と交趾への通路を抑え、東は珠江水系に接する。東晋の大興元年（318年）に晋興郡が置かれ、唐代には邕管経略使が置かれ邕州を治め、北宋の狄青は夜間に崑崙関を奪取して儂智高を平定した。元の泰定元年（1324年）に「南疆安寧」の意から南寧と改称された。",
