      "summaryJa": "姒姓の諸侯国。勾践が呉を滅ぼし覇者となった後、琅琊に遷都した。戦国初期、越王翳は斉を畏れて南遷し、呉（姑蘇）に戻った。前306年、越王無彊は北方の斉を伐ったが、斉の使者の説得により矛先を楚に向けた。楚の懐王に大敗させられ殺されたため、楚は旧呉の地から浙江に至るまでを全て奪取した。越国はこれにより閩越、東甌などの百越諸部に分裂した。"
