      "summaryZh": "周初、殷商の子孫である微子啓が商丘に封じられた国。礼楽の大国であり、墨子、荘子も宋の人であった。戦国中期には戴氏の剔成が司城として専権を振るった。前318年、宋王偃は自立して王を称し、東は斉を、南は楚を、西は魏を破った。彭城に遷都し、「五千乗の強宋」と称された。前286年、斉の湣王は魏・楚の軍と連合して宋を滅ぼし、その領土を三分した。",
