      "summaryJa": "405年、東晉の益州兵が桓振討伐のための東下を拒んで兵変を起こし、安西府参軍の譙縱を主君に擁立した。彼らは成都を攻め取り成都王と自称し、史に譙蜀と称される。後に後秦の姚興に称藩した。413年、劉裕は朱齡石を派遣し、「函中密詔」を用いて奇襲部隊を成都の外水へ直進させた。譙縱は兵敗れて自縊し、巴蜀は東晉に復帰した。"
