      "summaryJa": "1368年、明軍が大都に攻め入ると、元順帝は上都へ北走し、元朝廷は漠北に退去した。これを史に北元と称する。ココ・テムル（王保保）は1372年の嶺北の戦いで明軍を大敗させた。1388年、藍玉が捕魚兒海の戦いで北元を大破し、トグス・テムルは弑殺された。これ以後、モンゴルは韃靼と瓦剌に分裂した。"
